//       否则答案恒为 1。
// 为什么是 1：数组非递减 ⟺ 数组里不存在逆序对 (i<j 且 a[i]>a[j])。
//       先取定一对逆序对 (i,j)。只要这两个元素还在数组里，就仍能找到这对逆序对，
//       数组就不是非递减、游戏不会结束 —— 所以可以放心地一个个删掉其它元素；
//       等只剩 i、j 两个（此时 a[i]>a[j]，仍不是非递减，游戏继续），
//       再删掉其中一个，数组长度变成 1，长度为 1 一定非递减，游戏结束。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        bool sorted = true;                  // 数组是否已经非递减
        for (int i = 0; i + 1 < n; i++)
            if (a[i] > a[i + 1]) sorted = false;   // 出现相邻逆序即「不是非递减」

        cout << (sorted ? n : 1) << "\n";     // 已排好就一个都删不掉；否则能删到只剩 1 个
    }
    return 0;
}
```

### 易错点

不能在已经有序后继续删除，因此已排序数组的答案不是一。

